// ==============================
// GET RAW DATA FROM PREVIOUS NODES
// ==============================

const makeData =
  $('Make.com Information').first().json.organization;

const voiceflowData =
  $('Voiceflow Analytics').first().json.result.items;

const vapiData =
  $('Vapi Analytics').first().json.result;

const twilioData =
  $('Twilio Analytics').first().json.usage_records;



// ==============================
// MAKE.COM ANALYSIS
// ==============================

const makeReport = {
  plan: makeData.productName,
  operationsLimit: Number(makeData.license.operations || 0),
  operationsUsed: Number(makeData.operations || 0),
  operationsRemaining: Number(makeData.unusedOperations || 0),

  creditsUsed:
    Number(makeData.centicreditsConsumed || 0) / 100,

  creditsRemaining:
    Number(makeData.unusedCenticredits || 0) / 100,

  transferUsedMB:
    (
      Number(makeData.transfer || 0) /
      1024 /
      1024
    ).toFixed(2),

  activeScenarios: makeData.activeScenarios,
  activeApps: makeData.activeApps,

  nextReset: makeData.nextReset
};


// ==============================
// VOICEFLOW ANALYSIS
// ==============================

let totalAI = 0;
let totalInteractions = 0;

const modelStats = {};
const interactionStats = {};
const dailyUsage = {};

for (const item of voiceflowData) {

  const date = item.period.split("T")[0];

  // DAILY USAGE
  if (!dailyUsage[date]) {
    dailyUsage[date] = 0;
  }

  dailyUsage[date] += item.count;

  // AI USAGE
  if (
    item.type === "llm-input" ||
    item.type === "llm-output"
  ) {

    totalAI += item.count;

    if (!modelStats[item.model]) {
      modelStats[item.model] = {
        input: 0,
        output: 0
      };
    }

    if (item.type === "llm-input") {
      modelStats[item.model].input += item.count;
    }

    if (item.type === "llm-output") {
      modelStats[item.model].output += item.count;
    }
  }

  // INTERACTIONS
  if (item.type === "interaction") {

    totalInteractions += item.count;

    if (!interactionStats[item.model]) {
      interactionStats[item.model] = 0;
    }

    interactionStats[item.model] += item.count;
  }
}


// ==============================
// MOST USED MODEL
// ==============================

let mostUsedModel = "";
let highestModelUsage = 0;

for (const model in modelStats) {

  const total =
    modelStats[model].input +
    modelStats[model].output;

  if (total > highestModelUsage) {
    highestModelUsage = total;
    mostUsedModel = model;
  }
}


// ==============================
// HIGHEST USAGE DAY
// ==============================

let highestUsageDay = "";
let highestUsage = 0;

for (const day in dailyUsage) {

  if (dailyUsage[day] > highestUsage) {
    highestUsage = dailyUsage[day];
    highestUsageDay = day;
  }
}


// ==============================
// FORMAT MODEL TABLE
// ==============================

const aiBreakdown = [];

for (const model in modelStats) {

  aiBreakdown.push({
    model,
    inputUsage: modelStats[model].input,
    outputUsage: modelStats[model].output,
    total:
      modelStats[model].input +
      modelStats[model].output
  });
}


// ==============================
// FORMAT INTERACTION TABLE
// ==============================

const interactionBreakdown = [];

for (const source in interactionStats) {

  interactionBreakdown.push({
    source,
    count: interactionStats[source]
  });
}


// ==============================
// FORMAT DAILY TREND
// ==============================

const dailyTrend = [];

for (const day in dailyUsage) {

  dailyTrend.push({
    date: day,
    totalUsage: dailyUsage[day]
  });
}


// ==============================
// VOICEFLOW FINAL REPORT
// ==============================

const voiceflowReport = {
  totalAIOperations: totalAI,
  totalInteractions,
  mostUsedModel,
  highestUsageDay,
  aiBreakdown,
  interactionBreakdown,
  dailyTrend,

  notes: [
    "Counts represent usage events, not exact billing.",
    "Voiceflow API does not expose exact USD costs.",
    "AI usage estimated using llm-input and llm-output."
  ]
};


// ==============================
// VAPI ANALYSIS
// ==============================

let totalCalls = 0;
let totalDuration = 0;
let totalCost = 0;

let llmCost = 0;
let sttCost = 0;
let ttsCost = 0;
let transportCost = 0;
let vapiCost = 0;

const assistantBreakdown = [];

for (const item of vapiData) {

  totalCalls += Number(item.totalCalls || 0);

  totalDuration += Number(item.totalDuration || 0);

  totalCost += Number(item.totalCost || 0);

  llmCost += Number(item.llmCost || 0);

  sttCost += Number(item.sttCost || 0);

  ttsCost += Number(item.ttsCost || 0);

  transportCost += Number(item.transportCost || 0);

  vapiCost += Number(item.vapiCost || 0);

  assistantBreakdown.push({
    assistantId: item.assistantId,
    totalCalls: Number(item.totalCalls || 0),
    totalDuration: Number(item.totalDuration || 0).toFixed(2),
    avgDuration: Number(item.avgDuration || 0).toFixed(2),
    totalCost: Number(item.totalCost || 0).toFixed(4)
  });
}


// ==============================
// VAPI FINAL REPORT
// ==============================

const vapiReport = {

  totalCalls,

  totalDurationMinutes:
    totalDuration.toFixed(2),

  avgCallDuration:
    totalCalls > 0
      ? (totalDuration / totalCalls).toFixed(2)
      : 0,

  totalCost:
    totalCost.toFixed(4),

  costBreakdown: {
    llmCost: llmCost.toFixed(4),
    sttCost: sttCost.toFixed(4),
    ttsCost: ttsCost.toFixed(4),
    transportCost:
      transportCost.toFixed(4),
    vapiCost:
      vapiCost.toFixed(4)
  },

  assistantBreakdown
};


// ==============================
// TWILIO ANALYSIS
// ==============================

let twilioTotalCost = 0;
const twilioCategoryBreakdown = [];
const twilioServiceGroups = {
  sms: 0,
  voice: 0,
  whatsapp: 0,
  wireless: 0,
  video: 0,
  other: 0
};

for (const record of twilioData) {

  const cost = Number(record.price || 0);

  // Skip zero-cost records for the breakdown
  if (cost === 0) continue;

  twilioTotalCost += cost;

  // Push to per-category breakdown
  twilioCategoryBreakdown.push({
    category: record.category,
    description: record.description,
    cost: cost.toFixed(4),
    usage: record.usage,
    usageUnit: record.usage_unit,
    count: record.count,
    countUnit: record.count_unit,
    date: record.start_date
  });

  // Group into service buckets
  const cat = record.category;

  if (cat.startsWith("sms")) {
    twilioServiceGroups.sms += cost;
  } else if (
    cat.startsWith("calls") ||
    cat.startsWith("trunking") ||
    cat.startsWith("programmablevoice")
  ) {
    twilioServiceGroups.voice += cost;
  } else if (cat.startsWith("channels-whatsapp")) {
    twilioServiceGroups.whatsapp += cost;
  } else if (cat.startsWith("wireless")) {
    twilioServiceGroups.wireless += cost;
  } else if (
    cat.startsWith("pv-") ||
    cat.startsWith("group-rooms") ||
    cat.startsWith("peer-to-peer")
  ) {
    twilioServiceGroups.video += cost;
  } else {
    twilioServiceGroups.other += cost;
  }
}


// ==============================
// TWILIO FINAL REPORT
// ==============================

const twilioReport = {

  totalCost:
    twilioTotalCost.toFixed(4),

  currency: "usd",

  // Only services that actually had cost
  activeCategoryCount:
    twilioCategoryBreakdown.length,

  costByService: {
    sms:       twilioServiceGroups.sms.toFixed(4),
    voice:     twilioServiceGroups.voice.toFixed(4),
    whatsapp:  twilioServiceGroups.whatsapp.toFixed(4),
    wireless:  twilioServiceGroups.wireless.toFixed(4),
    video:     twilioServiceGroups.video.toFixed(4),
    other:     twilioServiceGroups.other.toFixed(4)
  },

  // Full line-item detail (only non-zero rows)
  categoryBreakdown: twilioCategoryBreakdown,

  notes: [
    "Prices pulled from Twilio Usage Records Daily endpoint.",
    "Zero-cost categories are excluded from breakdown.",
    "All costs in USD."
  ]
};


// ==============================
// FINAL EXECUTIVE SUMMARY
// ==============================

const executiveSummary = {

  make: {
    operationsUsed:
      makeReport.operationsUsed,

    creditsUsed:
      makeReport.creditsUsed
  },

  voiceflow: {
    aiOperations:
      voiceflowReport.totalAIOperations,

    interactions:
      voiceflowReport.totalInteractions
  },

  vapi: {
    totalCalls:
      vapiReport.totalCalls,

    totalCost:
      vapiReport.totalCost
  },

  // ✅ Added Twilio to executive summary
  twilio: {
    totalCost:
      twilioReport.totalCost,

    activeCategoryCount:
      twilioReport.activeCategoryCount
  }
};


// ==============================
// RETURN FINAL STRUCTURED REPORT
// ==============================

return [
  {
    json: {
      generatedAt:
        new Date().toISOString(),

      executiveSummary:
        executiveSummary || {},

      makeReport:
        makeReport || {},

      voiceflowReport:
        voiceflowReport || {},

      vapiReport:
        vapiReport || {},

      // ✅ New
      twilioReport:
        twilioReport || {}
    }
  }
];
